CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, role text NOT NULL CHECK(role IN ('teacher','student')), password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS classes(id uuid PRIMARY KEY, name text NOT NULL, teacher_id uuid NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS memberships(class_id uuid REFERENCES classes(id), user_id uuid REFERENCES users(id), PRIMARY KEY(class_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id uuid PRIMARY KEY, class_id uuid NOT NULL REFERENCES classes(id), title text NOT NULL, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rules(id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id), version int NOT NULL, template_version text NOT NULL, criteria jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id,version));
CREATE TABLE IF NOT EXISTS submissions(id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id), user_id uuid NOT NULL REFERENCES users(id), rule_id uuid NOT NULL REFERENCES rules(id), sha256 text NOT NULL, files jsonb NOT NULL, request_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,request_id));
CREATE TABLE IF NOT EXISTS runs(id uuid PRIMARY KEY, submission_id uuid NOT NULL REFERENCES submissions(id), status text NOT NULL CHECK(status IN ('queued','building','analyzing','review','published','infra_error','cancelled')), outcome text, results jsonb NOT NULL DEFAULT '[]', evidence jsonb NOT NULL DEFAULT '[]', feedback jsonb NOT NULL DEFAULT '[]', reviewed jsonb NOT NULL DEFAULT '[]', revision int NOT NULL DEFAULT 0, model_status text NOT NULL DEFAULT 'pending', execution_config jsonb NOT NULL, lease_token uuid, lease_until timestamptz, attempts int NOT NULL DEFAULT 0, request_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, UNIQUE(submission_id,request_id));
CREATE INDEX IF NOT EXISTS runs_queue_idx ON runs(status,created_at);
CREATE TABLE IF NOT EXISTS reports(id uuid PRIMARY KEY, run_id uuid UNIQUE NOT NULL REFERENCES runs(id), snapshot jsonb NOT NULL, published_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS revisions(id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id), user_id uuid NOT NULL REFERENCES users(id), revision int NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS events(id bigserial PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id), kind text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable record'; END; $$;
DROP TRIGGER IF EXISTS rules_immutable ON rules;
CREATE TRIGGER rules_immutable BEFORE UPDATE OR DELETE ON rules FOR EACH ROW EXECUTE FUNCTION immutable_record();
DROP TRIGGER IF EXISTS submissions_immutable ON submissions;
CREATE TRIGGER submissions_immutable BEFORE UPDATE OR DELETE ON submissions FOR EACH ROW EXECUTE FUNCTION immutable_record();
DROP TRIGGER IF EXISTS reports_immutable ON reports;
CREATE TRIGGER reports_immutable BEFORE UPDATE OR DELETE ON reports FOR EACH ROW EXECUTE FUNCTION immutable_record();
